//! Ebook repair sweep: stale and missing derived files.
//!
//! The on-demand EPUBs the web reader converts into `{storage_root}/books/`
//! used to be regenerated by nothing — a changed source or a deleted file
//! left the old row in place forever. The sweep must now flag both.

use crate::common::*;
use api::jobs::handlers::EbookRepairHandler;
use api::jobs::worker::JobHandler;
use api::repositories::book_files;
use filetime::{FileTime, set_file_mtime};
use serde_json::{Value, json};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use time::OffsetDateTime;
use tokio::sync::Semaphore;
use tokio_util::sync::CancellationToken;
use uuid::Uuid;

/// A minimal valid EPUB: one zip entry, no documents, so the defect checks
/// stay silent and only the staleness findings speak.
fn minimal_epub() -> Vec<u8> {
    let mut buf = Vec::new();
    {
        let mut zip = zip::ZipWriter::new(std::io::Cursor::new(&mut buf));
        let opts: zip::write::SimpleFileOptions = Default::default();
        zip.start_file("content.opf", opts).unwrap();
        zip.write_all(b"<package/>").unwrap();
        zip.finish().unwrap();
    }
    buf
}

fn repair_handler(server: &TestServer) -> EbookRepairHandler {
    EbookRepairHandler::new(
        server.pool.clone(),
        server.storage_root(),
        server.nats_publisher.clone(),
        Arc::new(Semaphore::new(1)),
    )
}

/// A book with a real source file on disk and a derived EPUB recorded as
/// converted from it. `recorded_mtime` is the source's mtime the row claims
/// to have been converted against.
async fn setup_derived_book(
    server: &TestServer,
    recorded_mtime: Option<OffsetDateTime>,
) -> (Uuid, PathBuf, PathBuf, Uuid) {
    let book_id = create_book(server, "Derived Book").await;
    let storage_root = server.storage_root();

    let source_path = Path::new(&storage_root).join("media").join("book.mobi");
    tokio::fs::create_dir_all(source_path.parent().unwrap())
        .await
        .unwrap();
    tokio::fs::write(&source_path, b"fake mobi source")
        .await
        .unwrap();

    let derived_path = Path::new(&storage_root)
        .join("books")
        .join(book_id.to_string())
        .join("book.epub");
    tokio::fs::create_dir_all(derived_path.parent().unwrap())
        .await
        .unwrap();
    let epub = minimal_epub();
    tokio::fs::write(&derived_path, &epub).await.unwrap();

    book_files::create(
        &server.pool,
        book_files::BookFileInput {
            book_id,
            format: "MOBI".to_string(),
            size_bytes: 18,
            file_path: source_path.to_string_lossy().to_string(),
            source_path: None,
            source_mtime: None,
            file_hash: None,
            source_type: Some("test".to_string()),
            source_metadata: None,
            ingest_queue_id: None,
        },
    )
    .await
    .unwrap();

    let derived_id = book_files::upsert_full(
        &server.pool,
        book_files::BookFileFullInput {
            book_id,
            format: "EPUB".to_string(),
            size_bytes: epub.len() as i64,
            file_path: derived_path.to_string_lossy().to_string(),
            source_path: Some(source_path.to_string_lossy().to_string()),
            source_mtime: recorded_mtime,
            file_hash: None,
            source_type: Some("on_demand_conversion".to_string()),
            source_metadata: Some(json!({ "source_format": "MOBI" })),
        },
    )
    .await
    .unwrap();

    (book_id, source_path, derived_path, derived_id)
}

async fn run_sweep(server: &TestServer) -> Value {
    repair_handler(server)
        .execute(
            Uuid::now_v7(),
            json!({ "dry_run": true }),
            CancellationToken::new(),
        )
        .await
        .expect("sweep failed")
}

#[tokio::test]
async fn test_sweep_flags_stale_on_demand_epub() {
    let server = TestServer::start_api_only().await;
    // Baseline recorded ten minutes ago; the source was written "now", so it
    // has changed since the conversion.
    let old = OffsetDateTime::now_utc() - time::Duration::minutes(10);
    let (book_id, _source, _derived, _id) = setup_derived_book(&server, Some(old)).await;

    let result = run_sweep(&server).await;
    let rework = result["needs_rework"]
        .as_array()
        .expect("needs_rework array");
    assert_eq!(
        rework.len(),
        1,
        "exactly one derived file should be flagged: {rework:?}"
    );
    assert_eq!(rework[0]["book_id"], book_id.to_string());
    let reasons = rework[0]["reasons"].as_array().unwrap();
    assert!(
        reasons
            .iter()
            .any(|r| r.as_str() == Some("source file changed since this was converted")),
        "expected a staleness reason, got {reasons:?}"
    );
}

#[tokio::test]
async fn test_sweep_flags_missing_derived_file() {
    let server = TestServer::start_api_only().await;
    let old = OffsetDateTime::now_utc() - time::Duration::minutes(10);
    let (_book_id, _source, derived_path, derived_id) =
        setup_derived_book(&server, Some(old)).await;

    // The file vanished from disk and the availability check marked the row.
    // The sweep must still see it: it is re-makeable from the source.
    tokio::fs::remove_file(&derived_path).await.unwrap();
    book_files::set_unavailable(&server.pool, derived_id)
        .await
        .unwrap();

    let result = run_sweep(&server).await;
    let rework = result["needs_rework"]
        .as_array()
        .expect("needs_rework array");
    assert_eq!(
        rework.len(),
        1,
        "the missing derived file should be flagged: {rework:?}"
    );
    let reasons = rework[0]["reasons"].as_array().unwrap();
    assert!(
        reasons.iter().any(|r| {
            r.as_str() == Some("derived file missing from disk; the original is still present")
        }),
        "expected a missing-file reason, got {reasons:?}"
    );
}

#[tokio::test]
async fn test_sweep_ignores_fresh_derived_file() {
    let server = TestServer::start_api_only().await;
    // No recorded baseline (a legacy row): the fallback compares on-disk
    // mtimes. The derived file was written after the source, so it is not
    // stale, and a valid EPUB has no defects.
    setup_derived_book(&server, None).await;

    let result = run_sweep(&server).await;
    let rework = result["needs_rework"]
        .as_array()
        .expect("needs_rework array");
    assert!(rework.is_empty(), "nothing should be flagged: {rework:?}");
}

#[tokio::test]
async fn test_sweep_ignores_derived_file_matching_recorded_baseline() {
    let server = TestServer::start_api_only().await;
    let (_book_id, source_path, _derived, derived_id) = setup_derived_book(&server, None).await;

    // Refresh the baseline to the source's actual mtime, as a repair does.
    let mtime = std::fs::metadata(&source_path).unwrap().modified().unwrap();
    let current = api::repositories::media_root_files::mtime_from_system_time(mtime);
    book_files::mark_rewritten(
        &server.pool,
        derived_id,
        100,
        Some(source_path.to_string_lossy().as_ref()),
        Some(current),
    )
    .await
    .unwrap();

    let result = run_sweep(&server).await;
    let rework = result["needs_rework"]
        .as_array()
        .expect("needs_rework array");
    assert!(rework.is_empty(), "nothing should be flagged: {rework:?}");
}

#[tokio::test]
async fn test_sweep_flags_stale_kepub_without_recorded_source() {
    let server = TestServer::start_api_only().await;
    let book_id = create_book(&server, "Kepub Book").await;
    let storage_root = server.storage_root();
    let source_path = Path::new(&storage_root).join("media").join("book.azw3");
    tokio::fs::create_dir_all(source_path.parent().unwrap())
        .await
        .unwrap();
    tokio::fs::write(&source_path, b"fake azw3 source")
        .await
        .unwrap();
    book_files::create(
        &server.pool,
        book_files::BookFileInput {
            book_id,
            format: "AZW3".to_string(),
            size_bytes: 18,
            file_path: source_path.to_string_lossy().to_string(),
            source_path: None,
            source_mtime: None,
            file_hash: None,
            source_type: Some("test".to_string()),
            source_metadata: None,
            ingest_queue_id: None,
        },
    )
    .await
    .unwrap();
    // A KEPUB the way the watcher registers one: no recorded source.
    let kepub_path = Path::new(&storage_root)
        .join("books")
        .join(book_id.to_string())
        .join("book.kepub");
    tokio::fs::create_dir_all(kepub_path.parent().unwrap())
        .await
        .unwrap();
    tokio::fs::write(&kepub_path, minimal_epub()).await.unwrap();
    book_files::create(
        &server.pool,
        book_files::BookFileInput {
            book_id,
            format: "KEPUB".to_string(),
            size_bytes: 100,
            file_path: kepub_path.to_string_lossy().to_string(),
            source_path: None,
            source_mtime: None,
            file_hash: None,
            source_type: Some("watch_directory".to_string()),
            source_metadata: None,
            ingest_queue_id: None,
        },
    )
    .await
    .unwrap();
    // The KEPUB was made ten minutes ago; the original was written since.
    let past = OffsetDateTime::now_utc() - time::Duration::minutes(10);
    set_file_mtime(
        &kepub_path,
        FileTime::from_unix_time(past.unix_timestamp(), 0),
    )
    .unwrap();
    let result = run_sweep(&server).await;
    let rework = result["needs_rework"]
        .as_array()
        .expect("needs_rework array");
    assert_eq!(
        rework.len(),
        1,
        "the stale KEPUB should be flagged: {rework:?}"
    );
    assert_eq!(rework[0]["book_id"], book_id.to_string());
    let reasons = rework[0]["reasons"].as_array().unwrap();
    assert!(
        reasons
            .iter()
            .any(|r| r.as_str() == Some("source file changed since this was converted")),
        "expected a staleness reason, got {reasons:?}"
    );
}

#[tokio::test]
async fn test_reader_skips_ghost_epub_row() {
    let server = TestServer::start_api_only().await;
    let book_id = create_book(&server, "Ghost Book").await;
    let storage_root = server.storage_root();

    // An EPUB row whose file is not on disk.
    book_files::create(
        &server.pool,
        book_files::BookFileInput {
            book_id,
            format: "EPUB".to_string(),
            size_bytes: 100,
            file_path: format!("{storage_root}/books/{book_id}/ghost.epub"),
            source_path: None,
            source_mtime: None,
            file_hash: None,
            source_type: Some("on_demand_conversion".to_string()),
            source_metadata: None,
            ingest_queue_id: None,
        },
    )
    .await
    .unwrap();

    // A real AZW3 on disk.
    let azw3_path = Path::new(&storage_root).join("media").join("book.azw3");
    tokio::fs::create_dir_all(azw3_path.parent().unwrap())
        .await
        .unwrap();
    let azw3_bytes = b"fake azw3 content".to_vec();
    tokio::fs::write(&azw3_path, &azw3_bytes).await.unwrap();
    book_files::create(
        &server.pool,
        book_files::BookFileInput {
            book_id,
            format: "AZW3".to_string(),
            size_bytes: azw3_bytes.len() as i64,
            file_path: azw3_path.to_string_lossy().to_string(),
            source_path: None,
            source_mtime: None,
            file_hash: None,
            source_type: Some("test".to_string()),
            source_metadata: None,
            ingest_queue_id: None,
        },
    )
    .await
    .unwrap();

    // The ghost EPUB must not shadow the readable AZW3.
    let resp = server
        .admin_client()
        .get(&format!("/api/v1/admin/books/{book_id}/file"))
        .await;
    resp.assert_ok();
    assert_eq!(resp.bytes(), azw3_bytes.as_slice());
}
